input.command:
cat > ui-driver/UITests/UITests.swift <<'EOF'
import XCTest

final class UITests: XCTestCase {
    func testNavigateAndOpenAttachmentMenu() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        sleep(2)
        let room = app.staticTexts.matching(identifier: "TitleLabel")
            .matching(NSPredicate(format: "label == %@", "Weekend Plans")).firstMatch
        XCTAssertTrue(room.waitForExistence(timeout: 10), "Weekend Plans room not found")
        room.tap()
        sleep(2)
        print("ELEMENT TREE ROOM\n\(app.debugDescription)")
    }
}
EOF
xcodebuild test -quiet -project ui-driver/UIDriver.xcodeproj -scheme UITests -destination 'platform=iOS Simulator,id=E3A04607-B440-44BA-BC55-8C11BF166E9D' CODE_SIGNING_ALLOWED=NO

